fn dir() -> PathBuf {
    fixture_dir().join("phase5c_hvkg")
}

fn load<T: DeserializeOwned>(name: &str) -> Option<T> {
    let path = dir().join(name);
    let text = std::fs::read_to_string(&path).ok()?;
    Some(serde_json::from_str(&text).unwrap_or_else(|e| panic!("{}: {e}", path.display())))
}

fn require<T: DeserializeOwned>(name: &str) -> T {
    load(name).unwrap_or_else(|| {
        panic!("{name} is missing; run scripts/generate_fixtures.py --phase 5c-hvkg")
    })
}

// ---------------------------------------------------------------------------
// Builders
// ---------------------------------------------------------------------------

fn build_member(f: &ModelSpec) -> BatchedMultiOutputGP {
    let c = &f.config;
    let x: Vec<Matrix> = f.train_x.iter().map(|b| matrix(b)).collect();
    let y: Vec<Matrix> = f.train_y.iter().map(|b| matrix(b)).collect();
    let mut options = BatchedMultiOutputGPOptions {
        train_yvar: f
            .train_yvar
            .as_ref()
            .map(|v| v.iter().map(|b| matrix(b)).collect()),
        ..Default::default()
    };
    if c.covar == "matern" {
        options.kernel = KernelKind::Matern52;
    }
    options.input_transform = match c.normalize.as_deref() {
        None => None,
        Some("shared") => Some(BatchedInputTransform::Shared(Normalize::new(c.d))),
        Some("explicit") => Some(BatchedInputTransform::Shared(
            Normalize::with_bounds(&matrix(c.bounds.as_ref().unwrap())).unwrap(),
        )),
        Some(other) => panic!("unknown normalize {other}"),
    };
    if c.outcome == "none" {
        options.outcome_transform = OutcomeTransformChoice::None;
    }
    let mut model = BatchedMultiOutputGP::new(x, y, vec![], options).unwrap();
    assert_eq!(model.num_outputs(), c.m);
    model.set_raw_parameters(&f.raw_params).unwrap();
    model
}

fn build_list(specs: &[ModelSpec]) -> ModelListGP {
    ModelListGP::new(specs.iter().map(build_member).collect()).unwrap()
}

/// `[c_k + Σ_j a_kj y_j + Σ_j b_kj y_j²]_k` and its row-major Jacobian.
fn generic(a: &[Vec<f64>], b: &[Vec<f64>], c: &[f64], y: &[f64]) -> (Vec<f64>, Vec<f64>) {
    let mut values = Vec::with_capacity(c.len());
    let mut jac = Vec::with_capacity(c.len() * y.len());
    for k in 0..c.len() {
        let s1: f64 = y.iter().zip(&a[k]).map(|(y, a)| y * a).sum();
        let s2: f64 = y.iter().zip(&b[k]).map(|(y, b)| y * y * b).sum();
        values.push(c[k] + s1 + s2);
        jac.extend(
            y.iter()
                .enumerate()
                .map(|(j, y)| a[k][j] + 2.0 * b[k][j] * y),
        );
    }
    (values, jac)
}

fn objective_of(spec: &Option<ObjectiveSpec>) -> Option<Arc<dyn McMultiOutputObjective>> {
    spec.as_ref().map(|s| -> Arc<dyn McMultiOutputObjective> {
        match s.clone() {
            ObjectiveSpec::Identity {
                outcomes,
                num_outcomes,
            } => Arc::new(
                IdentityMcMultiOutputObjective::new(Some(&outcomes), num_outcomes).unwrap(),
            ),
            ObjectiveSpec::Weighted {
                weights,
                outcomes,
                num_outcomes,
            } => Arc::new(
                WeightedMcMultiOutputObjective::new(
                    Vector::from_vec(weights),
                    outcomes.as_deref(),
                    num_outcomes,
                )
                .unwrap(),
            ),
            ObjectiveSpec::Generic { a, b, c } => {
                Arc::new(GenericMcMultiOutputObjective::new(move |y| {
                    generic(&a, &b, &c, y)
                }))
            }
        }
    })
}

/// A batch of matrices from a flat row-major array of shape
/// `batch × rows × cols`.
fn batched(data: &[f64], shape: &[usize]) -> BatchedMatrix {
    let (rows, cols) = (shape[shape.len() - 2], shape[shape.len() - 1]);
    let batch = shape[..shape.len() - 2].to_vec();
    let n: usize = batch.iter().product();
    let mats = (0..n)
        .map(|b| Matrix::from_row_slice(rows, cols, &data[b * rows * cols..(b + 1) * rows * cols]))
        .collect();
    BatchedMatrix::new(batch, mats).unwrap()
}

fn flat_json(v: &serde_json::Value, out: &mut Vec<f64>) {
    match v {
        serde_json::Value::Array(a) => a.iter().for_each(|x| flat_json(x, out)),
        serde_json::Value::Number(n) => out.push(n.as_f64().unwrap()),
        other => panic!("unexpected value {other}"),
    }
}

fn flat(v: &serde_json::Value) -> Vec<f64> {
    let mut out = Vec::new();
    flat_json(v, &mut out);
    out
}

fn sampler_from(rows: &[Vec<f64>]) -> Arc<SobolQMCNormalSampler> {
    Arc::new(SobolQMCNormalSampler::from_base_samples(matrix(rows), Some(UNRECORDED_SEED)).unwrap())
}

fn mask_of(rows: &[Vec<bool>]) -> BoolMatrix {
    let m = rows.first().map_or(0, |r| r.len());
    BoolMatrix::from_fn(rows.len(), m, |i, j| rows[i][j])
}

/// The joint posteriors of every batch element of a model at `x`, in
/// BoTorch's layout (means `batch × q × m`, covariances `batch × qm × qm`).
fn joints(post_at: &dyn Fn(usize) -> Posterior, n_batch: usize) -> (Vec<f64>, Vec<f64>) {
    let mut mean = Vec::new();
    let mut cov = Vec::new();
    for b in 0..n_batch {
        let p = post_at(b);
        let mm = p.mean_matrix();
        for i in 0..mm.nrows() {
            mean.extend(mm.row(i).iter());
        }
        for i in 0..p.covariance.nrows() {
            cov.extend(p.covariance.row(i).iter());
        }
    }
    (mean, cov)
}

// ---------------------------------------------------------------------------
// Conditioning and fantasies
// ---------------------------------------------------------------------------

/// A conditioned or fantasy model: a (batched) multi-output GP or a list.
enum Conditioned {
    Gp(BatchedMultiOutputGP),
    List(ModelListGP),
}

impl Conditioned {
    fn batch(&self) -> Vec<usize> {
        match self {
            Conditioned::Gp(g) => g.batch_shape().to_vec(),
            Conditioned::List(l) => l.batch_shape().to_vec(),
        }
    }

    fn posterior_at(&self, b: usize, x: &Matrix, noise: bool) -> Posterior {
        match self {
            Conditioned::Gp(g) => g.posterior_at(b, x, noise).unwrap(),
            Conditioned::List(l) => l.posterior_at(b, x, noise).unwrap(),
        }
    }
}

fn condition_case(model: &ConditionModel, c: &ConditionCase) -> Conditioned {
    let is_list = model.name.starts_with("list");
    if is_list {
        let list = build_list(&model.models);
        let m = list.num_outputs();
        if c.name == "condition_list" {
            let xs: Vec<BatchedMatrix> =
                c.xs.as_ref()
                    .unwrap()
                    .iter()
                    .map(|x| BatchedMatrix::single(matrix(x)))
                    .collect();
            let y =
                BatchedMatrix::single(Matrix::from_row_slice(2, m, &flat(c.y.as_ref().unwrap())));
            let noise = c
                .noise
                .as_ref()
                .map(|v| BatchedMatrix::single(Matrix::from_row_slice(2, m, &flat(v))));
            return Conditioned::List(
                list.condition_on_observations(&xs, &y, noise.as_ref())
                    .unwrap(),
            );
        }
        let x = batched(&flat(c.x.as_ref().unwrap()), c.x_shape.as_ref().unwrap());
        let n_f = c.num_fantasies.unwrap();
        let k = x.nrows();
        let draws: Vec<Option<Matrix>> = c
            .base_samples
            .as_ref()
            .unwrap()
            .as_array()
            .unwrap()
            .iter()
            .map(|v| {
                (!v.is_null()).then(|| {
                    let z = flat(v);
                    Matrix::from_row_slice(n_f, z.len() / n_f, &z)
                })
            })
            .collect();
        let mask = c.evaluation_mask.as_ref().map(|m| mask_of(m));
        let fm = if c.name == "fantasize_shared" {
            let s = SobolQMCNormalSampler::from_base_samples(
                draws[0].clone().unwrap(),
                Some(UNRECORDED_SEED),
            )
            .unwrap();
            list.fantasize(&x, FantasySampler::Shared(&s), None, None)
        } else {
            let samplers: Vec<Arc<SobolQMCNormalSampler>> = draws
                .iter()
                .map(|z| match z {
                    Some(z) => Arc::new(
                        SobolQMCNormalSampler::from_base_samples(z.clone(), Some(UNRECORDED_SEED))
                            .unwrap(),
                    ),
                    None => {
                        Arc::new(SobolQMCNormalSampler::new(n_f, Some(UNRECORDED_SEED)).unwrap())
                    }
                })
                .collect();
            list.fantasize(
                &x,
                FantasySampler::PerOutput(&samplers),
                None,
                mask.as_ref(),
            )
        };
        assert_eq!(k, 3);
        return Conditioned::List(fm.unwrap());
    }
    let gp = build_member(&model.models[0]);
    let m = gp.num_outputs();
    let x = batched(&flat(c.x.as_ref().unwrap()), c.x_shape.as_ref().unwrap());
    if c.name.starts_with("condition") {
        let ys = c.y_shape.as_ref().unwrap();
        assert_eq!(ys.last(), Some(&m));
        let y = batched(&flat(c.y.as_ref().unwrap()), ys);
        let noise = c.noise.as_ref().map(|v| batched(&flat(v), ys));
        return Conditioned::Gp(
            gp.condition_on_observations(&x, &y, noise.as_ref())
                .unwrap(),
        );
    }
    let n_f = c.num_fantasies.unwrap();
    let z = flat(&c.base_samples.as_ref().unwrap().clone());
    let s = SobolQMCNormalSampler::from_base_samples(
        Matrix::from_row_slice(n_f, z.len() / n_f, &z),
        Some(UNRECORDED_SEED),
    )
    .unwrap();
    let noise = c
        .observation_noise
        .as_ref()
        .map(|v| BatchedMatrix::single(matrix(v)));
    Conditioned::Gp(gp.fantasize(&x, &s, noise.as_ref()).unwrap())
}

fn check_conditioning(file: &str, report: &mut Report) -> usize {
    let Some(fixture) = load::<ConditionFixture>(file) else {
        return 0;
    };
    let mut count = 0;
    for model in &fixture.models {
        let x_test = matrix(&model.x_test);
        for c in &model.cases {
            let cm = condition_case(model, c);
            let batch = cm.batch();
            let n_batch: usize = batch.iter().product();
            let label = format!("{}/{}", model.name, c.name);
            for (noise, fx) in [(false, &c.posterior), (true, &c.posterior_noise)] {
                assert_eq!(
                    &fx.mean_shape[..fx.mean_shape.len() - 2],
                    batch.as_slice(),
                    "{label}: batch shape"
                );
                let (mean, cov) = joints(&|b| cm.posterior_at(b, &x_test, noise), n_batch);
                let what = if noise { " (noise)" } else { "" };
                report.check_slices(
                    &label,
                    &format!("mean{what}"),
                    &mean,
                    &vals(&fx.mean),
                    VALUE_TOL,
                );
                report.check_slices(
                    &label,
                    &format!("covariance{what}"),
                    &cov,
                    &vals(&fx.covariance),
                    VALUE_TOL,
                );
            }
            count += 1;
        }
    }
    count
}

#[test]
fn conditioning_and_fantasies_match_botorch() {
    let mut report = Report::default();
    let n = check_conditioning("conditioning.json", &mut report);
    assert!(n >= 20, "conditioning fixtures are missing ({n} cases)");
    let prs = check_conditioning("conditioning_3396.json", &mut report)
        + check_conditioning("conditioning_3399.json", &mut report);
    report.finish(&format!(
        "conditioning and fantasies ({n} cases, {prs} with pull requests)"
    ));
}

// ---------------------------------------------------------------------------
// The hypervolume knowledge gradient
// ---------------------------------------------------------------------------

fn cost_of(spec: &Option<CostSpec>) -> Option<Arc<dyn CostAwareUtility>> {
    spec.as_ref().map(|s| -> Arc<dyn CostAwareUtility> {
        let (model, log): (Arc<dyn CostModel>, bool) = match s {
            CostSpec::Fixed { fixed_cost, log } => (
                Arc::new(FixedCostModel::new(Vector::from_vec(fixed_cost.clone())).unwrap()),
                *log,
            ),
            CostSpec::Affine {
                weights,
                fixed_cost,
                log,
            } => (
                Arc::new(AffineFidelityCostModel::new(Some(weights), *fixed_cost).unwrap()),
                *log,
            ),
        };
        Arc::new(InverseCostWeightedUtility::new(model, true, None, log).unwrap())
    })
}

fn hvkg_of(list: &Arc<dyn Model>, c: &HvkgCase) -> Box<dyn AcquisitionFunction> {
    let m = list.num_outputs();
    let d = list.dim();
    let samplers: Vec<Arc<SobolQMCNormalSampler>> = c
        .base_samples
        .iter()
        .map(|z| match z {
            Some(z) => sampler_from(z),
            None => Arc::new(
                SobolQMCNormalSampler::new(c.num_fantasies, Some(UNRECORDED_SEED)).unwrap(),
            ),
        })
        .collect();
    assert_eq!(samplers.len(), m);
    let inner = match &c.inner_base_samples {
        Some(z) => sampler_from(z),
        None => Arc::new(
            SobolQMCNormalSampler::new(c.num_inner_samples, Some(UNRECORDED_SEED)).unwrap(),
        ),
    };
    let options = QHypervolumeKnowledgeGradientOptions {
        num_fantasies: c.num_fantasies,
        num_pareto: c.num_pareto,
        samplers: Some(samplers),
        objective: objective_of(&c.objective),
        inner_sampler: Some(inner),
        x_evaluation_mask: c.x_evaluation_mask.as_ref().map(|r| mask_of(r)),
        x_pending: c
            .x_pending
            .as_ref()
            .map(|p| Matrix::from_row_slice(p.len() / d, d, p)),
        x_pending_evaluation_mask: c.x_pending_evaluation_mask.as_ref().map(|r| mask_of(r)),
        current_value: c.current_value,
        use_posterior_mean: c.use_posterior_mean,
        cost_aware_utility: cost_of(&c.cost),
        log: c.log,
    };
    match &c.target_fidelities {
        Some(tf) => Box::new(
            QMultiFidelityHypervolumeKnowledgeGradient::new(
                Arc::clone(list),
                &c.ref_point,
                tf.clone(),
                QMultiFidelityHypervolumeKnowledgeGradientOptions {
                    hvkg: options,
                    project: Some(Arc::new(
                        TargetFidelityProjection::new(tf.clone(), d).unwrap(),
                    )),
                },
            )
            .unwrap(),
        ),
        None => Box::new(
            QHypervolumeKnowledgeGradient::new(Arc::clone(list), &c.ref_point, options).unwrap(),
        ),
    }
}

/// Error of values: relative, or absolute below 1 for log values.
fn value_err(a: f64, e: f64, log: bool) -> f64 {
    if log {
        (a - e).abs() / e.abs().max(1.0)
    } else {
        rel_err(&[a], &[e])
    }
}

#[test]
fn hypervolume_knowledge_gradient_matches_botorch() {
    let fixture: HvkgFixture = require("hvkg.json");
    let mut report = Report::default();
    let mut count = 0;
    let mut detached_gap: f64 = 0.0;
    for model in &fixture.models {
        let list: Arc<dyn Model> = Arc::new(build_list(&model.models));
        let d = list.dim();
        for c in &model.cases {
            let acqf = hvkg_of(&list, c);
            let label = format!("{}/{}", model.name, c.name);
            for (k, x) in c.x.iter().enumerate() {
                let xm = Matrix::from_row_slice(x.len() / d, d, x);
                assert_eq!(xm.nrows(), c.q + c.num_fantasies * c.num_pareto);
                let (v, g) = acqf.forward_with_grad(&xm).unwrap();
                assert_eq!(acqf.forward(&xm).unwrap(), v);
                let what = if c.log { "log value" } else { "value" };
                report.check(&label, what, value_err(v, c.values[k].0, c.log), VALUE_TOL);
                let expected = vals(&c.grads[k]);
                report.check_slices(
                    &label,
                    "gradient",
                    common::matrix_rows(&g).as_slice(),
                    &expected,
                    GRAD_TOL,
                );
                if !c.use_posterior_mean {
                    let det = vals(&c.grads_detached[k]);
                    detached_gap = detached_gap.max(rel_err(&det, &expected));
                }
                count += 1;
            }
        }
        for (k, vf) in model.value_functions.iter().enumerate() {
            let m = list.num_outputs();
            let sampler = vf.base_samples.as_ref().map(|z| sampler_from(z));
            let project: Option<Arc<dyn InputProjection>> = vf.project.then(|| {
                Arc::new(TargetFidelityProjection::new(vec![((d - 1) as isize, 1.0)], d).unwrap())
                    as _
            });
            let f = HypervolumeValueFunction::new(
                Arc::clone(&list),
                &vf.ref_point,
                objective_of(&vf.objective),
                sampler,
                vf.use_posterior_mean,
                vf.log,
                project,
            )
            .unwrap();
            let x = Matrix::from_row_slice(vf.x.len() / d, d, &vf.x);
            let (v, g) = f.forward_with_grad(&x).unwrap();
            let label = format!("{}/value_function_{k} (m = {m})", model.name);
            report.check(
                &label,
                "value function",
                value_err(v, vf.value.0, vf.log),
                VALUE_TOL,
            );
            report.check_slices(
                &label,
                "value function gradient",
                common::matrix_rows(&g).as_slice(),
                &vals(&vf.grad),
                GRAD_TOL,
            );
        }
    }
    for s in &fixture.split {
        let x = Matrix::from_row_slice(s.rows, 2, &s.x);
        let (a, f) = split_hvkg_fantasy_points(&x, s.n_f, s.num_pareto).unwrap();
        assert_eq!(common::matrix_rows(&a), s.actual);
        let fl: Vec<f64> = f.iter().flat_map(common::matrix_rows).collect();
        assert_eq!(fl, s.fantasies);
    }
    assert!(
        split_hvkg_fantasy_points(&Matrix::zeros(3, 2), 2, 2).is_err(),
        "too few points"
    );
    println!(
        "BoTorch's default (detached) gradients with posterior samples differ from the exact \
         ones by up to {detached_gap:.2e} (relative)"
    );
    assert!(
        count >= 50,
        "hvkg fixtures are missing ({count} evaluations)"
    );
    report.finish(&format!(
        "hypervolume knowledge gradient ({count} evaluations)"
    ));
}

// ---------------------------------------------------------------------------
// Optimization and initial conditions
// ---------------------------------------------------------------------------

#[test]
fn optimization_and_initial_conditions_match_botorch() {
    let fixture: OptimizeFixture = require("optimize.json");
    let mut report = Report::default();
    let (mut agree, mut total) = (0, 0);
    let (mut inner_agree, mut inner_total) = (0, 0);
    for model in &fixture.models {
        let list: Arc<dyn Model> = Arc::new(build_list(&model.models));
        let d = list.dim();
        let bounds = matrix(&model.bounds);
        for run in &model.runs {
            let n_f = run.num_fantasies;
            let options = QHypervolumeKnowledgeGradientOptions {
                num_fantasies: n_f,
                num_pareto: run.num_pareto,
                samplers: Some(run.base_samples.iter().map(|z| sampler_from(z)).collect()),
                inner_sampler: Some(match &run.inner_base_samples {
                    Some(z) => sampler_from(z),
                    None => Arc::new(SobolQMCNormalSampler::new(4, Some(UNRECORDED_SEED)).unwrap()),
                }),
                use_posterior_mean: run.use_posterior_mean,
                ..Default::default()
            };
            let acqf =
                QHypervolumeKnowledgeGradient::new(Arc::clone(&list), &run.ref_point, options)
                    .unwrap();
            let q_aug = acqf.get_augmented_q_batch_size(run.q);
            let per = q_aug * d;
            let ics: Vec<Matrix> = run
                .initial_conditions
                .chunks(per)
                .map(|c| Matrix::from_row_slice(q_aug, d, c))
                .collect();
            let opts = OptimizeAcqfOptions {
                batch_initial_conditions: Some(ics.clone()),
                batch_limit: Some(1),
                seed: Some(0),
                ..Default::default()
            };
            let r = optimize_acqf_detailed(&acqf, &bounds, run.q, ics.len(), 0, &opts).unwrap();
            assert_eq!(r.candidates.shape(), (run.q, d));
            for (i, rs) in r.restarts.iter().enumerate() {
                let expected = &run.candidates[i * per..(i + 1) * per];
                let err = rel_err(&common::matrix_rows(&rs.candidates), expected);
                let verr = value_err(rs.acq_value, run.values[i], false);
                println!(
                    "restart {i}: value {} vs BoTorch {} (candidates differ by {err:.2e})",
                    rs.acq_value, run.values[i]
                );
                total += 1;
                if verr <= 1e-6 {
                    agree += 1;
                    // The candidates need not agree: the value is flat in
                    // the dominated fantasy designs.
                    report.check(&model.name, "restart value (agreeing)", verr, 1e-6);
                }
            }
        }
        for ic in &model.ics {
            let samplers: Vec<Arc<SobolQMCNormalSampler>> = ic
                .base_samples
                .iter()
                .map(|z| match z {
                    Some(z) => sampler_from(z),
                    None => Arc::new(
                        SobolQMCNormalSampler::new(ic.num_fantasies, Some(UNRECORDED_SEED))
                            .unwrap(),
                    ),
                })
                .collect();
            let base = QHypervolumeKnowledgeGradientOptions {
                num_fantasies: ic.num_fantasies,
                num_pareto: ic.num_pareto,
                samplers: Some(samplers),
                ..Default::default()
            };
            let mut options = OptimizeAcqfOptions {
                seed: Some(ic.seed),
                eta: ic.eta,
                ..Default::default()
            };
            options.one_shot.num_inner_restarts = ic.inner_restarts;
            options.one_shot.raw_inner_samples = ic.inner_restarts;
            options.one_shot.eta = Some(ic.eta);
            let mf = ic.multi_fidelity.then(|| {
                QMultiFidelityHypervolumeKnowledgeGradient::new(
                    Arc::clone(&list),
                    &ic.ref_point,
                    ic.target_fidelities.clone().unwrap(),
                    QMultiFidelityHypervolumeKnowledgeGradientOptions {
                        hvkg: base.clone(),
                        project: None,
                    },
                )
                .unwrap()
            });
            let plain = (!ic.multi_fidelity).then(|| {
                QHypervolumeKnowledgeGradient::new(Arc::clone(&list), &ic.ref_point, base.clone())
                    .unwrap()
            });
            let acqf: &QHypervolumeKnowledgeGradient = match (&mf, &plain) {
                (Some(m), _) => m.as_hvkg(),
                (_, Some(p)) => p,
                _ => unreachable!(),
            };
            let (n_f, np, q) = (ic.num_fantasies, ic.num_pareto, ic.q);
            // 1. The inner optimization of the value function from the same
            //    raw samples (all optimized).
            let sol = optimize_hvkg_value_function(acqf, &bounds, &options).unwrap();
            let free: Vec<usize> = match &ic.target_fidelities {
                Some(tf) => (0..d)
                    .filter(|c| {
                        !tf.iter()
                            .any(|&(k, _)| (if k < 0 { d as isize + k } else { k }) as usize == *c)
                    })
                    .collect(),
                None => (0..d).collect(),
            };
            let df = free.len();
            let bt_inner: Vec<Matrix> = ic
                .inner_candidates
                .chunks(np * df)
                .map(|c| Matrix::from_row_slice(np, df, c))
                .collect();
            for (i, (c, v)) in sol.candidates.iter().zip(&sol.values).enumerate() {
                let verr = value_err(*v, ic.inner_values[i], false);
                inner_total += 1;
                if verr <= 1e-6 {
                    inner_agree += 1;
                    report.check(&model.name, "inner value (agreeing)", verr, 1e-6);
                    let reduced = Matrix::from_fn(np, df, |p, j| c[(p, free[j])]);
                    report.check(
                        &model.name,
                        "inner designs (agreeing)",
                        rel_err(
                            &common::matrix_rows(&reduced),
                            &common::matrix_rows(&bt_inner[i]),
                        ),
                        1e-6,
                    );
                }
            }
            // 2. BoTorch's fantasy designs are inner solutions, and the
            //    candidates selected with them fixed agree.
            let q_aug = q + n_f * np;
            let ic_options = InitialConditionOptions {
                seed: Some(ic.seed),
                eta: ic.eta,
                ..Default::default()
            };
            for r in 0..ic.num_restarts {
                let block = &ic.initial_conditions[r * q_aug * d..(r + 1) * q_aug * d];
                let full = Matrix::from_row_slice(q_aug, d, block);
                let fantasies = full.rows(q, n_f * np).into_owned();
                for i in 0..n_f {
                    let set = fantasies.rows(i * np, np);
                    let reduced = Matrix::from_fn(np, df, |p, j| set[(p, free[j])]);
                    let found = bt_inner.iter().any(|c| {
                        rel_err(&common::matrix_rows(&reduced), &common::matrix_rows(c)) == 0.0
                    });
                    assert!(found, "restart {r}: fantasy {i} is not an inner solution");
                }
                let mut rng = Xoshiro256PlusPlus::seed_from_u64(1);
                let (got, _) = gen_batch_initial_conditions_with_fantasies(
                    acqf,
                    &bounds,
                    q,
                    1,
                    ic.raw_samples,
                    &ic_options,
                    Some(&fantasies),
                    &mut rng,
                )
                .unwrap();
                report.check(
                    &model.name,
                    "candidates with fixed fantasy designs",
                    rel_err(&common::matrix_rows(&got[0]), &common::matrix_rows(&full)),
                    1e-12,
                );
            }
            // 3. The complete initial conditions: augmented sets whose fantasy
            //    designs are the Rust inner solutions.
            let mut rng = Xoshiro256PlusPlus::seed_from_u64(1);
            let (ics, _) = acqf
                .gen_one_shot_initial_conditions(
                    &bounds,
                    q,
                    ic.num_restarts,
                    ic.raw_samples,
                    &options,
                    &mut rng,
                )
                .unwrap();
            assert_eq!(ics.len(), ic.num_restarts);
            for x in &ics {
                assert_eq!(x.shape(), (q_aug, d));
                for i in 0..n_f {
                    let set = x.rows(q + i * np, np).into_owned();
                    assert!(sol.candidates.contains(&set));
                }
            }
        }
    }
    // Restarts from identical initial conditions reach BoTorch's value.
    report.check(
        "all",
        "restarts reaching BoTorch's value",
        1.0 - agree as f64 / total as f64,
        0.2,
    );
    if inner_total > 0 {
        report.check(
            "all",
            "inner restarts reaching BoTorch's value",
            1.0 - inner_agree as f64 / inner_total as f64,
            0.2,
        );
    }
    report.finish(&format!(
        "optimize_acqf ({agree} of {total} restarts agree; inner optimization of the one-shot initial conditions: {inner_agree} of {inner_total})"
    ));
}

// ---------------------------------------------------------------------------
// Cost models and fidelity helpers
// ---------------------------------------------------------------------------

#[test]
fn cost_models_and_fidelity_helpers_match_botorch() {
    let f: CostFixture = require("cost.json");
    let mut report = Report::default();
    let x = Matrix::from_row_slice(3, 4, &f.x);
    for a in &f.affine {
        let m = AffineFidelityCostModel::new(a.weights.as_deref(), a.fixed_cost).unwrap();
        let c = m.forward(&x).unwrap();
        report.check_slices("affine", "cost", c.as_slice(), &a.cost, EXACT_TOL);
    }
    let fixed =
        Arc::new(FixedCostModel::new(Vector::from_vec(f.fixed[0].fixed_cost.clone())).unwrap());
    let c = fixed.forward(&x).unwrap();
    report.check_slices(
        "fixed",
        "cost",
        &common::matrix_rows(&c),
        &f.fixed[0].cost,
        EXACT_TOL,
    );
    for (k, u) in f.utility.iter().enumerate() {
        let model: Arc<dyn CostModel> = if u.model == "affine" {
            Arc::new(AffineFidelityCostModel::new(Some(&[(3, 2.0)]), 0.5).unwrap())
        } else {
            fixed.clone()
        };
        let util = InverseCostWeightedUtility::new(model, true, None, u.log).unwrap();
        let mask = u.mask.as_ref().map(|r| mask_of(r));
        let out = util.evaluate(&x, &u.deltas, mask.as_ref(), false).unwrap();
        report.check_slices(
            &format!("utility_{k}"),
            "utility",
            &out.values,
            &u.values,
            EXACT_TOL,
        );
        // use_mean = false gives the same for deterministic cost models.
        let sampled =
            InverseCostWeightedUtility::new(util.cost_model().clone(), false, None, u.log)
                .unwrap()
                .evaluate(&x, &u.deltas, mask.as_ref(), false)
                .unwrap();
        assert_eq!(sampled.values, out.values);
    }
    for p in &f.project {
        let xp = Matrix::from_row_slice(3, p.cols, &p.x);
        let got = project_to_target_fidelity(&xp, &p.target_fidelities, p.d).unwrap();
        report.check_slices(
            "project",
            "projection",
            &common::matrix_rows(&got),
            &p.projected,
            0.0,
        );
    }
    for e in &f.expand {
        let got =
            expand_trace_observations(&x, e.fidelity_dims.as_deref(), e.num_trace_obs).unwrap();
        assert_eq!(got.nrows(), e.rows);
        report.check_slices(
            "expand",
            "trace observations",
            &common::matrix_rows(&got),
            &e.expanded,
            EXACT_TOL,
        );
    }
    report.finish("cost models and fidelity helpers");
}
